nextflow_process {

    name "Test Process CUTADAPT"
    script "../main.nf"
    process "CUTADAPT"

    tag "modules"
    tag "modules_nfcore"
    tag "cutadapt"

    test("sarscov2 - fastq - single-end") {

        when {
            process {
                """
                input[0] = [
                    [ id: 'test', single_end:true ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ]
                ]
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert snapshot(
                    process.out.reads,
                    file(process.out.log[0][1]).readLines()[3..10], // skip python version (differs between conda and container) and core count (depends on runner)
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }
    }

    test("sarscov2 - fastq - paired-end") {

        when {
            process {
                """
                input[0] = [
                    [ id: 'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ]
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert snapshot(
                    process.out.reads,
                    file(process.out.log[0][1]).readLines()[3..14], // skip python version (differs between conda and container) and core count (depends on runner)
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }
    }

    test("sarscov2 - fastq - single-end - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id: 'test', single_end:true ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ]
                ]
                """
            }
        }

        then {
            assertAll (
                { assert snapshot(
                    process.out.reads,
                    process.out.log,
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }
    }
}

